def can_cross(grid, start_r, target_row, start_c=None, target_col=None):
    """Check if there's any path of non-zeros from a row to target_row."""
    rows, cols = grid.shape

    # Check all starting positions in start_r that can reach target_row
    for c_start in range(cols):
        if grid[start_r, c_start] != 0:
            visited = set([(start_r, c_start)])
            queue = deque([(start_r, c_start)])

            while queue:
                r, c = queue.popleft()

                if r == target_row:
                    return True

                for dr, dc in [(-1,0),(1,0),(0,-1),(0,1)]:
                    nr, nc = r + dr, c + dc
                    if 0 <= nr < rows and 0 <= nc < cols:
                        if (nr, nc) not in visited and grid[nr, nc] != 0:
                            visited.add((nr, nc))
                            queue.append((nr, nc))

    return False

