def center_sees_center(g, c1_r, c1_c, c2_r, c2_c):
    """Check if cell at (c1_r,c1_c) can see cell at (c2_r,c2_c)."""
    r1, c1, r2, c2 = int(c1_r), int(c1_c), int(c2_r), int(c2_c)

    # Check horizontal line of sight
    if r1 == r2:
        min_c, max_c = min(c1,c2), max(c1,c2)
        for c in range(min_c+1, max_c):
            if g[r1, c] == 0:
                return False
        return True

    # Check vertical line of sight
    if c1 == c2:
        min_r, max_r = min(r1,r2), max(r1,r2)
        for r in range(min_r+1, max_r):
            if g[r, c1] == 0:
                return False
        return True

    # Diagonal? Check both diagonals
    if abs(r1-r2) == abs(c1-c2):
        dr, dc = sign_val := ((r2-r1) // abs(r2-r1)) if r2 != r1 else 0, ((c2-c1) // abs(c2-c1)) if c2 != c1 else 0

        rr, cc = r1 + dr * np.sign(r2-r1), c1 + dc * np.sign(c2-c1)
        while not (rr == r2 and cc == c2):
            if g[rr, cc] == 0:
                return False
            rr += dr
            cc += dc

        return True

    return False

def sign_val(d):
    return 1 if d > 0 else (-1 if d < 0 else 0)

